import {lightingLineClear,sceneryVisible} from './cave-lighting-masks.js';
import {traceTerrainTile,normalizeTerrainMask} from './campaign-cave-terrain.js';
// Approved type-2 native crack material, with bounded presentation-only motes.
export const FISSURE_SPEC=Object.freeze({maxCells:4096,tileDensity:4,maxSources:8,maxParticles:16,maxCacheSide:1536,color:'#ffc44b',core:'#fff0b3'});
export const CRACK_POLYGONS=Object.freeze([
 [[-12,-5],[-4,-2],[-1,-4],[2,-2],[5,0],[12,3],[12,4],[4,2],[0,-.6],[-5,-.7],[-12,-3.6]],
 [[-1,-2],[1,-1],[4,-7],[2,-8],[2,-4]],
 [[4,1],[5,2],[2,7],[.5,8],[1,4]]
]);
export const CRACK_RIM=Object.freeze([[-10,-4.3],[-4,-1.4],[-1,-2],[4,1.2],[5,.6],[0,-3],[-4,-2.5]]);
const hash=n=>{n=Math.imul(n^n>>>16,0x45d9f3b);return ((n^n>>>16)>>>0)/4294967296;};
const polygon=(p,points)=>{points.forEach(([x,y],i)=>i?p.lineTo(x,y):p.moveTo(x,y));p.closePath();};
export const FISSURE_ORIGINS=Object.freeze([[6.6,2.35],[2.4,-5.3],[2,5]]);
export function sampleFissureParticles(sources,time=0,soft=false){if(soft)return [];const stamp=Number.isFinite(time)?Math.max(0,time):0,out=[];for(const s of sources.slice(0,FISSURE_SPEC.maxSources))for(let i=0;i<2;i++){const u=((stamp/(4.6+s.phase)+s.phase+i*.5)%1+1)%1,a=FISSURE_ORIGINS[(s.anchor+i)%FISSURE_ORIGINS.length],ox=s.px+a[0]*(s.variant&1?-1:1),oy=s.py+a[1]*(s.variant&2?-1:1);out.push({x:ox+Math.sin(u*4.1+s.phase*6.28)*u*1.25,y:oy-u*(13+s.phase*5),radius:.45+Math.sin(u*Math.PI)*.28,alpha:Math.sin(u*Math.PI)**1.3*.65,originX:ox,originY:oy,source:s});}return out.slice(0,FISSURE_SPEC.maxParticles);}
export function createFossilFissures(room,{makeCanvas}){
 const sprites=new Map();let cells=[],sources=[],particles=[],maskRef=null,signature=0,dead=false,revision=0,cacheKey='',surface=null,reveal=null,bounds=null,glow=null,clock=0,soft=false,blocked=new Set();
 function makeSprite(variant){if(sprites.has(variant))return sprites.get(variant);const emission=makeCanvas(104,80),opening=makeCanvas(104,80);for(const [canvas,night]of[[emission,false],[opening,true]]){const c=canvas.getContext('2d');c.setTransform(4,0,0,4,52,40);if(variant&1)c.scale(-1,1);if(variant&2)c.scale(1,-1);const cracks=new Path2D();for(const points of CRACK_POLYGONS)polygon(cracks,points);c.clip(cracks);const rim=new Path2D();rim.rect(-20,-20,40,40);polygon(rim,CRACK_RIM);c.clip(rim,'evenodd');
   if(night){c.fillStyle='#000000';c.globalAlpha=.96;c.fillRect(-13,-9,26,18);}
   else{c.fillStyle='#9d4617';c.globalAlpha=.30;c.fillRect(-13,-9,26,18);c.lineJoin='round';c.lineCap='round';const veins=[[[-11.8,-4.4],[-5,-1.75],[-1,-1.9],[4.4,.95],[11.8,3.55]],[[-.3,-1.85],[1.6,-4.25],[3,-7.25]],[[4.1,1.7],[2.6,4.5],[1.15,7.35]]];for(const points of veins){for(const [width,color,alpha]of[[1.25,'#ff872d',.24],[.52,FISSURE_SPEC.color,.86],[.18,FISSURE_SPEC.core,.80]]){c.strokeStyle=color;c.lineWidth=width;c.globalAlpha=alpha;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();}}}
  }const result={emission,opening};sprites.set(variant,result);return result;}
 function update(masks,{depth=0,time=0,soft:reduced=false}={}){if(dead)return;clock=Number.isFinite(time)?Math.max(0,time):0;soft=!!reduced;const cols=room.cols||21,rows=room.rows||15;let next=depth;for(const p of masks.cells)next=Math.imul(next^((p.y*cols+p.x)*7+(room.terrain?.[p.y*cols+p.x]||0)),16777619);if(maskRef!==masks||signature!==next){maskRef=masks;signature=next;revision++;blocked=new Set((room.rocks||[]).filter(n=>n.hp==null||n.hp>0).map(n=>n.x+','+n.y));const same=(x,y)=>x>=0&&y>=0&&x<cols&&y<rows&&room.floorMask[y*cols+x]&&room.terrain?.[y*cols+x]===2;cells=masks.cells.filter(p=>same(p.x,p.y)).slice(0,FISSURE_SPEC.maxCells).map(p=>{let mask=0;for(const[dx,dy,bit]of[[0,-1,1],[1,0,2],[0,1,4],[-1,0,8],[1,-1,16],[1,1,32],[-1,1,64],[-1,-1,128]])if(same(p.x+dx,p.y+dy))mask|=bit;const px=50+22*p.x+2*p.y,py=57.5+16*p.y,path=new Path2D(),seed=(room.seed||0)^Math.imul(p.x+31,977)^Math.imul(p.y+depth+17,157);traceTerrainTile(path,normalizeTerrainMask(mask),px,py);return {...p,px,py,path,variant:Math.floor(hash(room.seed+(p.y*cols+p.x)*157)*4),phase:hash(seed),anchor:Math.floor(hash(seed+31)*3),priority:hash(seed+691)};});sources=[];for(const p of [...cells].sort((a,b)=>a.priority-b.priority))if(sources.length<FISSURE_SPEC.maxSources&&sources.every(q=>Math.abs(q.x-p.x)+Math.abs(q.y-p.y)>=3))sources.push(p);bounds=cells.length?{x:Math.floor(Math.min(...cells.map(p=>p.px)))-14,y:Math.floor(Math.min(...cells.map(p=>p.py)))-11,w:Math.ceil(Math.max(...cells.map(p=>p.px))-Math.min(...cells.map(p=>p.px)))+28,h:Math.ceil(Math.max(...cells.map(p=>p.py))-Math.min(...cells.map(p=>p.py)))+22}:null;}particles=sampleFissureParticles(sources,clock,soft).filter(p=>{const gy=(p.y-57.5)/16,tile={x:Math.round((p.x-50-2*gy)/22),y:Math.round(gy)};return sceneryVisible(room,tile.x,tile.y)&&lightingLineClear(room,p.source,tile,blocked);});}
 function prepare(masks,gain){if(!bounds)return false;const key=revision+':'+Math.round(Math.min(1,gain)*100);if(cacheKey===key)return true;const b=bounds,scale=Math.min(2,FISSURE_SPEC.maxCacheSide/b.w,FISSURE_SPEC.maxCacheSide/b.h),w=Math.ceil(b.w*scale),h=Math.ceil(b.h*scale);surface??=makeCanvas(1,1);reveal??=makeCanvas(1,1);for(const image of[surface,reveal]){image.width=w;image.height=h;image.getContext('2d').setTransform(scale,0,0,scale,-b.x*scale,-b.y*scale);}for(const[image,part]of[[surface,'emission'],[reveal,'opening']]){const c=image.getContext('2d');c.save();c.clip(masks.floor);c.globalAlpha=Math.min(1,gain);for(const p of cells){c.save();c.clip(p.path);c.drawImage(makeSprite(p.variant)[part],p.px-13,p.py-10,26,20);c.restore();}c.restore();}cacheKey=key;return true;}
 function spark(){if(glow)return glow;glow=makeCanvas(24,24);const c=glow.getContext('2d'),g=c.createRadialGradient(12,12,0,12,12,12);g.addColorStop(0,'#ffc44bc0');g.addColorStop(.3,'#ffb52b60');g.addColorStop(1,'#ff872d00');c.fillStyle=g;c.fillRect(0,0,24,24);return glow;}
 return {update,sprite:makeSprite,paintGround(c,masks,{gain=1,duck=1}={}){if(dead||gain<=0||!prepare(masks,gain))return;c.save();c.globalCompositeOperation='screen';c.globalAlpha*=duck;c.drawImage(surface,bounds.x,bounds.y,bounds.w,bounds.h);c.restore();},paintNight(c,viewport,masks,{gain=1}={}){if(dead||gain<=0||!prepare(masks,gain))return;c.save();c.translate(-viewport.x+4,-viewport.y+4);c.globalAlpha=1;c.drawImage(reveal,bounds.x,bounds.y,bounds.w,bounds.h);c.clip(masks.floor);for(const p of particles){c.globalAlpha=Math.min(.65,p.alpha*gain);c.fillStyle='#000000';c.beginPath();c.arc(p.x,p.y,p.radius+1,0,Math.PI*2);c.fill();}c.restore();},paintParticles(c,masks,{gain=1,duck=1}={}){if(dead||gain<=0||!particles.length)return;c.save();c.globalCompositeOperation='screen';c.clip(masks.floor);for(const p of particles){c.globalAlpha=Math.min(1,p.alpha*gain*duck)*.22;c.drawImage(spark(),p.x-3,p.y-3,6,6);c.globalAlpha=Math.min(.9,p.alpha*gain*duck);c.fillStyle=FISSURE_SPEC.core;c.beginPath();c.ellipse(p.x,p.y,p.radius*.75,p.radius,0,0,Math.PI*2);c.fill();}c.restore();},status:()=>({cells:cells.length,sources:sources.length,particles:particles.length,variants:sprites.size,revision,time:clock,soft,cacheWidth:surface?.width||0,cacheHeight:surface?.height||0,canvasBytes:[surface,reveal,glow,...[...sprites.values()].flatMap(s=>[s.emission,s.opening])].filter(Boolean).reduce((n,c)=>n+c.width*c.height*4,0)}),dispose(){dead=true;for(const c of[surface,reveal,glow,...[...sprites.values()].flatMap(s=>[s.emission,s.opening])].filter(Boolean))c.width=c.height=1;sprites.clear();surface=reveal=glow=null;cells=[];sources=[];particles=[];maskRef=null;}};
}
